css:
.pd-shell{font:14px/1.45 system-ui,sans-serif;color:#172033;background:#f7f8fb;border:1px solid #dfe3ea;border-radius:16px;padding:20px}
.pd-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.pd-kicker{margin:0;color:#64748b;text-transform:uppercase;letter-spacing:.08em;font-size:11px}.pd-head h2{margin:3px 0 0;font-size:24px}
.pd-metrics{display:grid;grid-template-columns:repeat(3,minmax(110px,1fr));gap:10px}.pd-metric{background:white;border:1px solid #dfe3ea;border-radius:12px;padding:10px 12px}.pd-metric strong{display:block;font-size:22px}.pd-metric span{color:#64748b;font-size:12px}
.pd-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:18px}.pd-card{appearance:none;text-align:left;background:white;border:2px solid transparent;box-shadow:0 0 0 1px #dfe3ea;border-radius:14px;padding:16px;cursor:pointer;color:inherit}.pd-card:hover{box-shadow:0 0 0 1px #9aa6b2}.pd-card.is-active{border-color:#2563eb;background:#eff6ff}.pd-card-top{display:flex;justify-content:space-between;gap:12px;align-items:center}.pd-card h3{margin:0;font-size:17px}.pd-badge{font-size:11px;font-weight:700;border-radius:999px;padding:4px 8px;background:#eef2f7;color:#475569}.pd-badge[data-status="active"]{background:#dcfce7;color:#166534}.pd-active-note{min-height:18px;margin:10px 0 0;color:#2563eb;font-size:12px;font-weight:700}
@media(max-width:760px){.pd-head{display:block}.pd-metrics,.pd-cards{grid-template-columns:1fr}.pd-metrics{margin-top:14px}}

js:
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const cards=root.querySelector('.pd-cards'),metrics=root.querySelector('.pd-metrics');
function render(){
  const projects=api.getState('projects')||[];
  const tasks=api.getState('tasks')||[];
  const activeId=api.getState('activeProjectId');
  const activeCount=projects.filter(p=>String(p.status||'').toLowerCase()==='active').length;
  const openCount=tasks.filter(t=>String(t.status||'').toLowerCase()!=='done').length;
  metrics.innerHTML=[
    ['Projects',projects.length],['Active projects',activeCount],['Open tasks',openCount]
  ].map(([label,value])=>`<div class="pd-metric"><strong>${value}</strong><span>${label}</span></div>`).join('');
  cards.innerHTML=projects.map(p=>{
    const active=String(p.id)===String(activeId);
    const status=p.status||'Unknown';
    return `<button class="pd-card${active?' is-active':''}" type="button" role="listitem" data-id="${esc(p.id)}" aria-pressed="${active}">
      <div class="pd-card-top"><h3>${esc(p.name||p.title||p.id)}</h3><span class="pd-badge" data-status="${esc(String(status).toLowerCase())}">${esc(status)}</span></div>
      <p class="pd-active-note">${active?'Active project':''}</p>
    </button>`;
  }).join('');
}
cards.addEventListener('click',e=>{
  const card=e.target.closest('.pd-card'); if(!card)return;
  api.setState('activeProjectId',card.dataset.id);
  api.log(1,`Active project set to ${card.dataset.id}`);
});
const unsubscribe=api.subscribe(render);
render();
